/**
 * html2canvas loader for BugReport screenshot feature.
 *
 * This file is a CDN loader stub.  In production, either:
 *   (a) replace this file with the vendored html2canvas.min.js (SRI-pinned), or
 *   (b) load it from CDN at runtime using the script tag below.
 *
 * CDN (with SRI):
 *   <script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js"
 *           integrity="sha512-BNaRQnYJYiPSqHHDb58B0yaPfCu+Wgds8Gp/gU33kqBtgNS4tSPHuGibyoeqMV/TJlSKda6FXzoEyYGjTe+vXA=="
 *           crossorigin="anonymous" referrerpolicy="no-referrer"></script>
 *
 * PHI overlay: before capturing, blank any element with class `.phi`
 * (see client-side JS in app/components/bug_report.jl).
 *
 * Source: https://html2canvas.hertzen.com/
 * License: MIT
 */
(function (root) {
  'use strict';

  // If html2canvas is already loaded (e.g. via CDN), do nothing.
  if (root.html2canvas) return;

  // Attempt to load from CDN with a fallback no-op.
  var s = document.createElement('script');
  s.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
  s.integrity = 'sha512-BNaRQnYJYiPSqHHDb58B0yaPfCu+Wgds8Gp/gU33kqBtgNS4tSPHuGibyoeqMV/TJlSKda6FXzoEyYGjTe+vXA==';
  s.crossOrigin = 'anonymous';
  s.referrerPolicy = 'no-referrer';
  s.onerror = function () {
    console.warn('[BugReport] html2canvas failed to load — screenshot capture disabled.');
  };
  document.head.appendChild(s);
}(window));
